arguments.newString:
_BUREAU_TAG_RE = re.compile(
    r"\b(" + "|".join(sorted(_BUREAU_TAG_MAP, key=len, reverse=True)) + r")-B\d*\b"
)


def bureau_tags_from_text(text: str) -> Set[str]:
    """Map TUC-B1 / EXP-B1 / EQX-B1 / EFX-B1 (and comma-separated) to bureau keys."""
    found: Set[str] = set()
    upper = (text or "").upper()
    for token in _BUREAU_TAG_RE.findall(upper):
        prefix = token.split("-")[0]
        bureau = _BUREAU_TAG_MAP.get(prefix)
        if bureau:
            found.add(bureau)

arguments.oldString:
def bureau_tags_from_text(text: str) -> Set[str]:
    """Map TUC-B1 / EXP-B1 / EQX-B1 (and comma-separated) to bureau keys."""
    found: Set[str] = set()
    upper = (text or "").upper()
    for token in re.findall(r"\b(TUC|EXP|EQX|TU)-B\d*\b", upper):
        prefix = token.split("-")[0]
        bureau = _BUREAU_TAG_MAP.get(prefix)
        if bureau:
            found.add(bureau)

